(()=>{'use strict';
const C=window.FranklinAssistantCore;if(!C)return;let state=null,busy=false;
const lang=()=>String(document.documentElement.lang||'').toLowerCase().startsWith('es')?'es':'en',tx=(en,es)=>lang()==='es'?es:en;
const text=v=>String(v||'').replace(/\s+/g,' ').trim();
function sensitive(t){return/(\b\d{3}-\d{2}-\d{4}\b|social security|ssn|account number|routing number|medical record|password|contrase[nñ]a|numero de cuenta|seguro social)/i.test(t)}
function dates(t){return[...new Set((t.match(/\b(?:\d{1,2}[/-]){2}\d{2,4}\b|\b(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+\d{1,2}(?:,\s*\d{4})?/gi)||[]).slice(0,8))]}
function money(t){return[...new Set((t.match(/\$\s?\d[\d,]*(?:\.\d{2})?/g)||[]).slice(0,8))]}
function classify(t){const n=C.norm(t),rows=[['court or legal notice',/\b(court|summons|complaint|hearing|citation|plaintiff|defendant|attorney|legal notice|tribunal|audiencia|citacion)\b/],['bill, claim or insurance document',/\b(invoice|bill|claim|policy|premium|deductible|coverage|insurance|factura|reclamo|poliza|seguro)\b/],['health or medical document',/\b(patient|medical|doctor|clinic|hospital|medication|lab|diagnosis|paciente|medico|clinica|medicamento|diagnostico)\b/],['property, HOA or permit document',/\b(property|parcel|hoa|permit|zoning|contractor|inspection|propiedad|parcela|permiso|zonificacion)\b/],['benefits or government notice',/\b(benefit|eligibility|agency|department|notice|application|snap|medicaid|beneficio|elegibilidad|agencia|departamento)\b/]];return rows.find(x=>x[1].test(n))?.[0]||'document'}
function answer(t,q=''){const clean=text(t).slice(0,100000),ds=dates(clean),ms=money(clean),sent=clean.split(/(?<=[.!?])\s+/).filter(x=>x.length>=25&&x.length<=500),tokens=C.meaningful(q);const rank=s=>tokens.reduce((n,w)=>n+(C.norm(s).includes(w)?7:0),0)+(/\b(deadline|due|when|date|amount|how much|phone|address|fecha|plazo|monto|telefono|direccion)\b/i.test(q)&&/\d|\$/.test(s)?8:0);const chosen=(q?[...sent].sort((a,b)=>rank(b)-rank(a)).filter(s=>rank(s)>0).slice(0,3):sent.slice(0,3));const bits=[tx(`This looks like a ${classify(clean)}.`,`Esto parece ser un ${classify(clean)}.`)];if(ds.length)bits.push(tx(`Dates I found: ${ds.slice(0,5).join(', ')}.`,`Fechas encontradas: ${ds.slice(0,5).join(', ')}.`));if(ms.length)bits.push(tx(`Amounts I found: ${ms.slice(0,5).join(', ')}.`,`Montos encontrados: ${ms.slice(0,5).join(', ')}.`));if(chosen.length)bits.push(chosen.join(' '));return{text:bits.join(' '),sensitive:sensitive(clean)}}
function load(src,name){return new Promise((resolve,reject)=>{if(window[name])return resolve(window[name]);const old=document.querySelector(`script[data-fr-file-lib="${name}"]`);if(old){old.addEventListener('load',()=>resolve(window[name]),{once:true});old.addEventListener('error',reject,{once:true});return}const s=document.createElement('script');s.src=src;s.async=true;s.crossOrigin='anonymous';s.dataset.frFileLib=name;s.onload=()=>resolve(window[name]);s.onerror=reject;document.head.append(s)})}
async function pdf(file){const p=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@6.3.289/build/pdf.mjs');p.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@6.3.289/build/pdf.worker.mjs';const d=await p.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;let out='';for(let i=1;i<=Math.min(d.numPages,30);i++){const page=await d.getPage(i),c=await page.getTextContent();out+='\n'+c.items.map(x=>x.str).join(' ');if(out.length>100000)break}return out}
async function docx(file){await load('https://cdn.jsdelivr.net/npm/mammoth@1.12.2/mammoth.browser.min.js','mammoth');const r=await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return String(r.value||'').slice(0,100000)}
async function image(file,progress){await load('https://cdn.jsdelivr.net/npm/tesseract.js@7.0.0/dist/tesseract.min.js','Tesseract');const r=await window.Tesseract.recognize(file,lang()==='es'?'spa':'eng',{logger:m=>{if(m.status==='recognizing text'&&typeof m.progress==='number')progress(Math.round(m.progress*100))}});return String(r.data?.text||'').slice(0,100000)}
async function extract(file,progress){if(file.size>8*1024*1024)throw Error('FILE_TOO_LARGE');const n=file.name.toLowerCase(),type=file.type||'';if(type.startsWith('text/')||/\.(txt|md|csv|json|html?)$/.test(n))return(await file.text()).slice(0,100000);if(type==='application/pdf'||n.endsWith('.pdf'))return pdf(file);if(/wordprocessingml/.test(type)||n.endsWith('.docx'))return docx(file);if(type.startsWith('image/')||/\.(png|jpe?g|webp|bmp)$/.test(n))return image(file,progress);throw Error('UNSUPPORTED_FILE')}
function install(form,input){if(form.querySelector('[data-franklin-attachment]'))return;input.placeholder=tx('Example: I just moved here and need help setting up utilities.','Ejemplo: Acabo de mudarme aquí y necesito ayuda para configurar los servicios públicos.');const box=document.createElement('div');box.className='franklin-assistant-attach';box.dataset.franklinAttachment='1';const label=document.createElement('label');label.className='franklin-assistant-attach-label';label.textContent=tx('Attach a document, screenshot or photo with readable text (optional)','Adjuntar documento, captura o foto con texto legible (opcional)');const f=document.createElement('input');f.type='file';f.accept='.pdf,.docx,.txt,.md,.csv,.json,.html,image/png,image/jpeg,image/webp';f.className='franklin-assistant-file';f.setAttribute('aria-describedby','franklin-attachment-help');label.append(f);const status=document.createElement('div');status.className='franklin-assistant-file-status';status.setAttribute('aria-live','polite');const remove=document.createElement('button');remove.type='button';remove.className='link-button franklin-assistant-remove-file';remove.textContent=tx('Remove attachment','Quitar archivo');remove.hidden=true;const help=document.createElement('p');help.id='franklin-attachment-help';help.className='fine-print';help.textContent=tx('Files are read on this device when possible. File text is not sent to web search. Avoid passwords, account numbers, Social Security numbers or other highly sensitive information.','Los archivos se leen en este dispositivo cuando es posible. El texto del archivo no se envía a búsquedas web. Evite contraseñas, números de cuenta, Seguro Social u otra información muy sensible.');box.append(label,status,remove,help);const anchor=input.parentElement===form?input:input.parentElement;form.insertBefore(box,anchor.nextSibling);f.addEventListener('change',async()=>{const file=f.files?.[0];state=null;remove.hidden=true;if(!file){status.textContent='';return}busy=true;status.textContent=tx(`Reading ${file.name} on this device…`,`Leyendo ${file.name} en este dispositivo…`);try{const t=await extract(file,p=>status.textContent=tx(`Reading ${file.name}… ${p}%`,`Leyendo ${file.name}… ${p}%`));if(!text(t))throw Error('NO_TEXT');state={name:file.name,type:file.type,text:t};status.textContent=tx(`${file.name} is ready. Ask a question about it, or submit with the question box empty for a summary.`,`${file.name} está listo. Haga una pregunta o envíe con el cuadro vacío para obtener un resumen.`);remove.hidden=false}catch(e){status.textContent=e.message==='FILE_TOO_LARGE'?tx('That file is too large. Use a file under 8 MB.','El archivo es demasiado grande. Use uno menor de 8 MB.'):e.message==='UNSUPPORTED_FILE'?tx('That file type is not supported yet. Try PDF, DOCX, text, PNG, JPG or WebP.','Ese tipo de archivo aún no es compatible. Pruebe PDF, DOCX, texto, PNG, JPG o WebP.'):tx('I could not read enough text from that file. Try a clearer image or a text-based PDF.','No pude leer suficiente texto. Pruebe una imagen más clara o un PDF con texto.');f.value=''}finally{busy=false}});remove.addEventListener('click',()=>{state=null;f.value='';status.textContent='';remove.hidden=true})}
window.FranklinAssistantFilesR1293=Object.freeze({install,get:()=>state,isBusy:()=>busy,answer});
})();
